content:
cat << 'EOF' > /work/config.json
{
  "intervals": [1, 3, 7, 14, 30, 60, 120],
  "ease_factor_min": 1.3,
  "ease_factor_max": 2.5,
  "ease_factor_default": 2.5,
  "ease_update_easy": 0.15,
  "ease_update_hard": -0.20,
  "new_card_limit": 20,
  "review_card_limit": 100,
  "max_leech_fails": 8,
  "max_reviews_per_session": 200,
  "next_day_hour": 4,
  "min_interval": 1,
  "max_interval": 365,
  "leech_tag": "leech",

  "decks": {
    "spanish_basics": {
      "description": "Spanish-English Basics",
      "card_file": "spanish_basics.json",
      "active": true
    },
    "math_facts": {
      "description": "Basic Math Facts",
      "card_file": "math_facts.json",
      "active": true
    },
    "history_dates": {
      "description": "Key History Dates",
      "card_file": "history_dates.json",
      "active": false
    },
    "linux_commands": {
      "description": "Linux Command Cheat Sheet",
      "card_file": "linux_commands.json",
      "active": true
    }
  },

  "ui": {
    "show_answer_shortcut": "space",
    "rate_hard_shortcut": "1",
    "rate_good_shortcut": "2",
    "rate_easy_shortcut": "3",
    "exit_shortcut": "q"
  },

  "stats": {
    "session_history_limit": 50,
    "show_performance": true,
    "show_progress_bars": true
  },

  "logging": {
    "log_to_file": true,
    "log_file": "trainer.log"
  },

  "session_options": {
    "shuffle_new": true,
    "randomize_reviews": false
  }
} 
EOF

